package com.clearchoice;
import android.content.Context;import android.os.Handler;import android.os.Looper;import org.json.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import java.util.regex.*;
/** Optional local gateway for visual emphasis hints only. Source text and actions are immutable. */
public final class LayoutGateway {
 public interface Callback {void onResult(int revision,Set<String> emphasis,String failure,String mode);}
 static final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(1),r->{Thread t=new Thread(r,"ClearChoice-layout");t.setDaemon(true);return t;},new ThreadPoolExecutor.DiscardOldestPolicy());static final Handler main=new Handler(Looper.getMainLooper());static final LinkedHashMap<String,Set<String>> cache=new LinkedHashMap<String,Set<String>>(40,.75f,true){protected boolean removeEldestEntry(Map.Entry<String,Set<String>> e){return size()>40;}};
 static boolean enabled(Context c){return c.getSharedPreferences("cc",0).getBoolean("ai_enabled",false);}static String endpoint(Context c){return c.getSharedPreferences("cc",0).getString("ai_endpoint","http://10.0.2.2:8787/v1/evaluate");}
 static void evaluate(Context context,int revision,String screen,String profile,List<Engine.Item> source,Callback callback){if(!enabled(context))return;final String url=endpoint(context).trim();if(!url.startsWith("https://")&&!url.equals("http://10.0.2.2:8787/v1/evaluate")){callback.onResult(revision,Collections.emptySet(),"Only HTTPS endpoints are allowed outside the Android emulator gateway.","local-fallback");return;}String key=revision+"|"+screen+"|"+profile; synchronized(cache){if(cache.containsKey(key)){callback.onResult(revision,cache.get(key),null,"cached-source-review");return;}}final String intent=Profiles.effective(context,screen.substring(screen.lastIndexOf("|")+1)).getString("prompt","");final ArrayList<Engine.Item> nodes=new ArrayList<>(source);worker.execute(()->{Set<String> result=Collections.emptySet();String failure=null,mode="local-fallback";HttpURLConnection conn=null;try{JSONObject payload=request(revision,screen,profile,nodes,intent);URL u=new URL(url);if(!"https".equalsIgnoreCase(u.getProtocol())&&!url.equals("http://10.0.2.2:8787/v1/evaluate"))throw new IOException("Non-HTTPS endpoint rejected.");conn=(HttpURLConnection)u.openConnection();conn.setRequestMethod("POST");conn.setConnectTimeout(1600);conn.setReadTimeout(21000);conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json; charset=utf-8");byte[] bytes=payload.toString().getBytes("UTF-8");conn.setFixedLengthStreamingMode(bytes.length);try(OutputStream os=conn.getOutputStream()){os.write(bytes);}if(conn.getResponseCode()!=200)throw new IOException("Gateway returned HTTP "+conn.getResponseCode());String body;try(InputStream is=conn.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=is.read(b))!=-1){out.write(b,0,n);if(out.size()>65536)throw new IOException("Gateway response exceeded size limit.");}body=out.toString("UTF-8");}JSONObject parsed=new JSONObject(body);result=validate(parsed,revision,nodes);mode=parsed.optString("mode","local-fallback");synchronized(cache){cache.put(key,result);}}catch(Exception ex){failure=ex.getClass().getSimpleName()+": "+String.valueOf(ex.getMessage());}finally{if(conn!=null)conn.disconnect();}Set<String> safe=result;String err=failure,verifiedMode=mode;main.post(()->callback.onResult(revision,safe,err,verifiedMode));});}
 static JSONObject request(int revision,String screen,String profile,List<Engine.Item> items,String intent)throws JSONException{JSONObject req=new JSONObject(),perception=new JSONObject();perception.put("sourceRevision",String.valueOf(revision));perception.put("appKey",Engine.STORE);perception.put("screenKey",screen);JSONArray a=new JSONArray();for(Engine.Item i:items){if(i.clazz.toLowerCase(Locale.ROOT).contains("edittext"))continue;JSONObject n=new JSONObject();n.put("id",i.id);n.put("type",i.clickable?"button":"text");n.put("text",sanitize(i.value));n.put("visible",true);n.put("enabled",true);n.put("clickable",i.clickable);n.put("scrollable",i.scrollable);n.put("checked",i.checked);n.put("actions",new JSONArray().put(i.scrollable?"scroll":i.clickable?"click":"navigate"));a.put(n);}perception.put("elements",a);req.put("perception",perception);req.put("requestKind","review");req.put("aiConsent",true);String style=profile.toLowerCase(Locale.ROOT);req.put("layoutStyle",Arrays.asList("balanced","minimal","accessible").contains(style)?style:"balanced");req.put("layoutIntent",intent.isEmpty()?"Improve legibility using source-anchored annotations. Preserve all original text, prices, currency and controls.":sanitize(intent));return req;}
 static String sanitize(String value){String s=value.replaceAll("(?i)[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,}","[email]");s=s.replaceAll("(?<!\\d)(?:\\+?\\d[ .()\\-]*){9,}(?!\\d)","[number]");return s.length()>180?s.substring(0,180):s;}
 static Set<String> validate(JSONObject response,int revision,List<Engine.Item> items)throws JSONException{HashSet<String> allowed=new HashSet<>();for(Engine.Item i:items)allowed.add(i.id);LinkedHashSet<String> out=new LinkedHashSet<>();JSONArray suggestions=response.optJSONArray("suggestions");if(suggestions==null||suggestions.length()>50)throw new JSONException("Invalid suggestions.");for(int i=0;i<suggestions.length();i++){JSONObject v=suggestions.getJSONObject(i);String id=v.getString("sourceId");if(!v.getString("kind").equals("annotation"))throw new JSONException("Only annotations are allowed");if(!String.valueOf(revision).equals(v.getString("sourceRevision"))||!allowed.contains(id))throw new JSONException("Stale or unknown source reference.");out.add(id);}JSONObject layout=response.optJSONObject("layout");if(layout!=null){if(!String.valueOf(revision).equals(layout.getString("sourceRevision")))throw new JSONException("Stale layout.");JSONArray rows=layout.getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);for(String field:new String[]{"titleSourceId","priceSourceId","actionSourceId"})if(!allowed.contains(row.getString(field)))throw new JSONException("Unknown layout source reference.");out.add(row.getString("titleSourceId"));}}return Collections.unmodifiableSet(out);}
 private LayoutGateway(){}
}
